// Literais de coleção grandes e constantes (docs/NATIVO-PROJETOS-REAIS.md,
// causa C4): as tabelas Unicode e de codificação dos pacotes (`bidi`,
// `unorm_dart`, `enough_convert`) têm de 10 a 30 mil entradas. O getter da
// constante era uma função só, com um buffer de argumentos e uma palavra de
// derramamento por elemento: o quadro passava de 1 MiB e estourava a pilha
// do isolado principal (0xC00000FD), ou o LLVM ficava sem memória. A VM
// monta o literal num vetor (`StoreIndexed`) e chama `Map._fromLiteral`
// (kernel_binary_flowgraph.cc:4051-4140).
//
// Gerado (semente 7); os números dizem o que cada caso exercita.

enum Cat { lu, ll, nd, zs }

int resumo(Iterable<Object?> xs) {
  var h = 0;
  for (final x in xs) {
    h = (h * 31 + x.hashCode) & 0x3FFFFFFF;
  }
  return h;
}
